/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

export async function restoreOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set({ archivedAt: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();
  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Deleted workspaces old enough for the permanent retention sweep. */
export async function listDeletedOrgsBefore(before: string): Promise<readonly OrgId[]> {
  const rows = getDb().select({ id: organizations.id }).from(organizations)
    .where(and(isNotNull(organizations.archivedAt), lte(organizations.archivedAt, before))).all();
  return rows.map((row) => row.id as OrgId);
}

/** Remove the workspace and all tenant-owned state atomically. Global users and sessions survive. */
export async function purgeOrg(orgId: OrgId): Promise<void> {
  const db = getDb();
  db.transaction((tx) => {
    tx.update(sessions).set({ activeOrgId: null, updatedAt: toIsoTimestamp(new Date()) })
      .where(eq(sessions.activeOrgId, orgId)).run();
    for (const table of [webhookDeliveries, webhookEndpoints, searchIndex, rateLimitBuckets,
      notifications, notificationPreferences, activityEvents, invoices, subscriptions,
      attachments, issueLabels, comments, issues, labels, projectMembers, projects,
      invitations, members, organizationUsage]) {
      tx.delete(table).where(eq(table.orgId, orgId)).run();
    }
    tx.delete(organizations).where(eq(organizations.id, orgId)).run();
  }, { behavior: "immediate" });
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
